                sb.AppendLine("Conditions =>");
                using (sb.Brace())
                {
                    foreach (var subItem in ConditionsItem)
                    {
                        using (sb.Brace())
                        {
                            subItem?.Print(sb, "Item");
                        }
                    }
                }
            }
            if (printMask?.HGLB ?? true)
            {
                sb.AppendItem(item.HGLB.FormKeyNullable, "HGLB");
            }
            if ((printMask?.DOFA ?? true)
                && item.DOFA is {} DOFAItem)
            {
                sb.AppendLine($"DOFA => {SpanExt.ToHexString(DOFAItem)}");
            }
        }
        
